mapper.select:
SELECT share_token, COUNT(*) AS cnt FROM share_scan_log WHERE deleted = 0 AND share_token IN
#{token}
GROUP BY share_token

SELECT slc.target_id AS article_id, COUNT(DISTINCT sl.user_id) AS user_cnt FROM share_scan_log sl INNER JOIN share_live_code slc ON sl.share_token = slc.share_token WHERE sl.deleted = 0 AND sl.user_id > 0 AND sl.share_token IN
#{token}
GROUP BY slc.target_id
